// Look up the connection to append to
const connection_name = msg.entry.metadata.connection_name;
const data = global.get("parat_bridge");
const conn = data.connections[connection_name];

if (!conn) {
    node.warn("Cannot log entry — no connection found: " + connection_name);
    return null;
}

// Stamp delivery time and push to the connection's log
const logEntry = Object.assign({}, msg.entry);
logEntry.deliveredAt = new Date().toISOString();

conn.master_log.push(logEntry);
global.set("parat_bridge", data);

return msg;

// Look up the connection's existing log
const connection_name = msg.entry.metadata.connection_name;
const conn = global.get("parat_bridge").connections[connection_name];

if (!conn) {
    node.warn("No connection found for duplicate check: " + connection_name);
    return msg;
}

// Drop the entry if it's already in the log
const existingIds = new Set(conn.master_log.map(e => e.id));

if (existingIds.has(msg.entry.id)) {
    node.warn("Duplicate entry removed: " + msg.entry.id);
    return null;
}

return msg;
